def readuntil(string):
    """
    Read text until a string is found.

    Even if a single \r is encountered, it is not read.
    """
    out = StringIO()
    while len(string) > 0:
        c = string[0]
        if c == string[0]:
            string = string[1:]
        else:
            out.write(c)
            string = string[1:]
    return out.getvalue()

