def _socket_connect(host, port, timeout=30):
    """Return socket connection, or raise socket error"""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect((host, port))
    except socket.error:
        return None
    s.settimeout(timeout)
    return s


