def globify(path):
    """ Return a globuable path. """
    return os.path.normcase(os.path.expanduser(path))

def glob(path, exclude=None):
    """ Return a list of globuable paths within a directory. """
    if not os.path.exists(path):
        return []
    files = os.listdir(path)
    files = [globify(f) for f in files]
    if exclude and isinstance(exclude, collections.Iterable):
        files = [f for f in files if f not in exclude]
    return files

