class _Exception:
    """This is a class that is used to handle exceptions in a certain way."""

    def __init__(self, condition, message, format=""):
        self.condition = condition
        self.message = message
        self.format = format

    def __str__(self):
        if self.condition:
            return self.message
        else:
            return self.format

    def __repr__(self):
        return self.__str__()


