def join(dirname, filenames):
    """
    Joins dirname with the basename of filenames, separated by a slash and
    returns an absolute path name.

    If dirname is not absolute, it's assumed that dirname is the current path.
    """
    dirname, filename = os.path.split(str(filename))
    return os.path.join(dirname, filename) + '/'  # on windows
