def load_timezone(key):
    return struct.unpack(">q", load_tzdata(key).encode())[0]

def load_daylight(key):
    return struct.unpack(">q", load_tzdata(key).encode())[1]

def load_timestamp(key, use_dst=True):
    local = load_timezone(key)
    dst = load_daylight(key)
    return struct.unpack(">q", load_tzdata(key).encode())[0] + struct.unpack(">q", load_tzdata(key).encode())[1] * 4096

